			// starttime is field 22 globally, which is index 22-3=19 inside the
			// post-paren slice (fields 1, 2 (parenthesized comm), 3..N).
			const starttime = lastParen < 0 ? undefined : stat.slice(lastParen + 1).trim().split(/\s+/)[19];
